def longestDiverseString(a, b, c):
    from heapq import heappush, heappop
    result = []
    max_heap = []

    if a > 0:
        heappush(max_heap, (-a, 'a'))
    if b > 0:
        heappush(max_heap, (-b, 'b'))
    if c > 0:
        heappush(max_heap, (-c, 'c'))

    while len(max_heap) > 1:
        first = heappop(max_heap)
        second = heappop(max_heap)

        if -first[0] >= 2:
            add_count = min(2, -first[0])
            result.append(first[1] * add_count)
            first = (first[0] + add_count, first[1])
        else:
            result.append(first[1])
            first = (first[0] + 1, first[1])

        if -second[0] >= 2 and -second[0] >= -first[0]:
            add_count = min(2, -second[0])
            result.append(second[1] * add_count)
            second = (second[0] + add_count, second[1])
        else:
            result.append(second[1])
            second = (second[0] + 1, second[1])

        if first[0] < 0:
            heappush(max_heap, first)
        if second[0] < 0:
            heappush(max_heap, second)

    if max_heap:
        last = heappop(max_heap)
        if -last[0] >= 2:
            add_count = min(2, -(last[0]))
            result.append(last[1] * add_count)
        else:
            result.append(last[1])

    return ''.join(result)
